import demo.fabricbridge.fabric.api.attachment.v1.AttachmentRegistry;
import demo.fabricbridge.fabric.api.attachment.v1.AttachmentTarget;
import demo.fabricbridge.fabric.api.attachment.v1.AttachmentType;
import net.minecraft.resources.Identifier;
import net.minecraft.server.level.ServerPlayer;
import net.neoforged.fml.config.ModConfig;
import net.neoforged.neoforge.common.ModConfigSpec;

public class Notes {
	public static final AttachmentType<Boolean> GOT_NOTE = AttachmentRegistry.create(
		Identifier.fromNamespaceAndPath("demo", "got_note"),
		builder -> builder.initializer(() -> false).persistent(Codec.BOOL).copyOnDeath()
	);

	public static void init(ModConfigSpec spec) {
		ModConfigEvents.loading("demo").register(config -> spec.afterReload());
		ConfigRegistry.INSTANCE.register("demo", ModConfig.Type.LOCAL, spec);
	}

	static void join(ServerPlayer player) {
		if (!AttachmentTarget.getAttachedOrCreate(player, GOT_NOTE)) {
			AttachmentTarget.setAttached(player, GOT_NOTE, true);
		}
	}
}
